-- Pantry LK — standard units (base, wall and corner cabinets) for the Products page.
-- Generated from lib/planner/site-products.ts. Photos are rendered from the Kitchen Planner models
-- (public/images/products, regenerate at /dev/product-renders in development).
-- Prices follow LKR 7,100 per sq ft of front; the site recalculates price, sizes and specs from code.

-- Run after 0001_init.sql (creates the tables). The two categories are added here too, so this
-- file also works when 0002_seed.sql hasn't been run.

begin;


select 'standard-base-cabinet', 'Standard Base Cabinet', c.id, 'Door base unit in four standard widths.', 'Our standard base cupboard with an adjustable shelf: 750 mm high and 560 mm deep, in 200, 400, 600 or 800 mm widths. Units of 800 mm have two doors.', 'starting', 11464, '[{"name": "Matte White", "hex": "#f1efea"}, {"name": "Natural Oak", "hex": "#c69c6d"}, {"name": "Grey High-Gloss", "hex": "#9a9c9d"}, {"name": "Pantry Navy", "hex": "#1f3550"}, {"name": "Sage Green", "hex": "#8b9a7f"}, {"name": "Walnut", "hex": "#5b3b26"}]'::jsonb, '[]'::jsonb, false, 'published', 20, now()
from public.product_categories c where c.slug = 'base-cabinets' on conflict (slug) do nothing;
select 'three-drawer-base-unit', 'Three-Drawer Base Unit', c.id, 'One shallow and two deep drawers.', 'A drawer base unit for cutlery, pots and pans: one shallow and two deep drawers, 750 mm high and 560 mm deep.', 'starting', 22927, '[{"name": "Matte White", "hex": "#f1efea"}, {"name": "Natural Oak", "hex": "#c69c6d"}, {"name": "Grey High-Gloss", "hex": "#9a9c9d"}, {"name": "Pantry Navy", "hex": "#1f3550"}, {"name": "Sage Green", "hex": "#8b9a7f"}, {"name": "Walnut", "hex": "#5b3b26"}]'::jsonb, '[]'::jsonb, false, 'published', 21, now()
from public.product_categories c where c.slug = 'base-cabinets' on conflict (slug) do nothing;
select 'l-shaped-corner-base-unit', 'L-Shaped Corner Base Unit', c.id, 'Uses the whole corner, with a door on each side.', 'An L-shaped corner unit that turns the base cabinets round the corner with no dead space. It measures 900 mm along each wall, 750 mm high, with a door on each inside face.', 'starting', 71074, '[{"name": "Matte White", "hex": "#f1efea"}, {"name": "Natural Oak", "hex": "#c69c6d"}, {"name": "Grey High-Gloss", "hex": "#9a9c9d"}, {"name": "Pantry Navy", "hex": "#1f3550"}, {"name": "Sage Green", "hex": "#8b9a7f"}, {"name": "Walnut", "hex": "#5b3b26"}]'::jsonb, '[]'::jsonb, false, 'published', 22, now()
from public.product_categories c where c.slug = 'base-cabinets' on conflict (slug) do nothing;
select 'blind-corner-base-unit', 'Blind Corner Base Unit', c.id, 'A single door; the blind side runs under the next worktop.', 'A corner base unit for where two runs meet: the blind side tucks under the run on the other wall, leaving one door at the front. 800 or 1000 mm wide, 750 mm high, 560 mm deep.', 'starting', 45854, '[{"name": "Matte White", "hex": "#f1efea"}, {"name": "Natural Oak", "hex": "#c69c6d"}, {"name": "Grey High-Gloss", "hex": "#9a9c9d"}, {"name": "Pantry Navy", "hex": "#1f3550"}, {"name": "Sage Green", "hex": "#8b9a7f"}, {"name": "Walnut", "hex": "#5b3b26"}]'::jsonb, '[]'::jsonb, false, 'published', 23, now()
from public.product_categories c where c.slug = 'base-cabinets' on conflict (slug) do nothing;
select 'standard-wall-cabinet', 'Standard Wall Cabinet', c.id, 'Door wall unit in four standard widths.', 'Our standard wall cupboard with two shelves: 750 mm high and 350 mm deep, in 200, 400, 600 or 800 mm widths.', 'starting', 11464, '[{"name": "Matte White", "hex": "#f1efea"}, {"name": "Natural Oak", "hex": "#c69c6d"}, {"name": "Grey High-Gloss", "hex": "#9a9c9d"}, {"name": "Pantry Navy", "hex": "#1f3550"}, {"name": "Sage Green", "hex": "#8b9a7f"}, {"name": "Walnut", "hex": "#5b3b26"}]'::jsonb, '[]'::jsonb, false, 'published', 24, now()
