select 'glass-door-wall-cabinet', 'Glass-Door Wall Cabinet', c.id, 'Framed glass doors for display.', 'A wall cabinet with framed glass doors to show off glassware and crockery. Add an LED strip inside to light the shelves.', 'starting', 22927, '[{"name": "Matte White", "hex": "#f1efea"}, {"name": "Natural Oak", "hex": "#c69c6d"}, {"name": "Grey High-Gloss", "hex": "#9a9c9d"}, {"name": "Pantry Navy", "hex": "#1f3550"}, {"name": "Sage Green", "hex": "#8b9a7f"}, {"name": "Walnut", "hex": "#5b3b26"}]'::jsonb, '[]'::jsonb, false, 'published', 25, now()
