select 'lift-up-wall-cabinet', 'Lift-Up Wall Cabinet', c.id, 'A horizontal front that lifts up and stays open.', 'A low horizontal wall cabinet with a lift-up front, ideal above the hood or along the top of a run.', 'starting', 18342, '[{"name": "Matte White", "hex": "#f1efea"}, {"name": "Natural Oak", "hex": "#c69c6d"}, {"name": "Grey High-Gloss", "hex": "#9a9c9d"}, {"name": "Pantry Navy", "hex": "#1f3550"}, {"name": "Sage Green", "hex": "#8b9a7f"}, {"name": "Walnut", "hex": "#5b3b26"}]'::jsonb, '[]'::jsonb, false, 'published', 26, now()
