from public.product_categories c where c.slug = 'wall-cabinets' on conflict (slug) do nothing;
select 'open-wall-shelf-unit', 'Open Wall Shelf Unit', c.id, 'Open shelving to break up a run of wall units.', 'An open wall unit with shelves, 750 mm high and 350 mm deep, in 200, 400 or 600 mm widths.', 'starting', 11464, '[{"name": "Matte White", "hex": "#f1efea"}, {"name": "Natural Oak", "hex": "#c69c6d"}, {"name": "Grey High-Gloss", "hex": "#9a9c9d"}, {"name": "Pantry Navy", "hex": "#1f3550"}, {"name": "Sage Green", "hex": "#8b9a7f"}, {"name": "Walnut", "hex": "#5b3b26"}]'::jsonb, '[]'::jsonb, false, 'published', 28, now()
from public.product_categories c where c.slug = 'wall-cabinets' on conflict (slug) do nothing;

commit;
