insert into public.product_categories (slug, name, description, image_path, image_alt, sort_order) values ('base-cabinets', 'Base cabinets', 'Drawers and cupboards that carry the worktop.', '/images/oak-base-units.jpg', 'Oak-finish base cabinets with handleless drawers', 1) on conflict (slug) do nothing;
insert into public.product_categories (slug, name, description, image_path, image_alt, sort_order) values ('wall-cabinets', 'Wall cabinets', 'Solid, glass and open options above the counter.', '/images/glass-wall-units.jpg', 'Black-framed glass wall cabinets above a stone backsplash', 2) on conflict (slug) do nothing;
insert into public.products (slug, name, category_id, summary, description, price_mode, price, finishes, specs, is_featured, status, sort_order, published_at)
insert into public.product_images (product_id, path, alt, sort_order) select id, '/images/products/standard-base-cabinet.jpg', 'Standard Base Cabinet in Matte White', 0 from public.products where slug = 'standard-base-cabinet' and not exists (select 1 from public.product_images pi join public.products pp on pp.id = pi.product_id where pp.slug = 'standard-base-cabinet' and pi.path = '/images/products/standard-base-cabinet.jpg');
insert into public.product_images (product_id, path, alt, sort_order) select id, '/images/products/standard-base-cabinet-open.jpg', 'Standard Base Cabinet with doors open', 1 from public.products where slug = 'standard-base-cabinet' and not exists (select 1 from public.product_images pi join public.products pp on pp.id = pi.product_id where pp.slug = 'standard-base-cabinet' and pi.path = '/images/products/standard-base-cabinet-open.jpg');
